package io.github.jhipster.sample.web.rest;

import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;

@Controller
public class ClientForwardController {

    /**
     * Forwards any unmapped paths (except those containing a period) to the client {@code index.html}.
     * <p>
     * Spring 6 uses {@code PathPatternParser} by default, which does not allow a {@code **} in the middle of a pattern
     * (such as {@code /**}{@code /{path:[^\\.]*}}). The nested client routes are therefore listed explicitly, up to
     * five path segments deep, and the last segment of each path must not contain a period.
     * @return forward to client {@code index.html}.
     */
    @GetMapping(
        value = {
            "/{path:[^\\.]+}",
            "/{p1:[^\\.]+}/{path:[^\\.]+}",
            "/{p1:[^\\.]+}/{p2:[^\\.]+}/{path:[^\\.]+}",
            "/{p1:[^\\.]+}/{p2:[^\\.]+}/{p3:[^\\.]+}/{path:[^\\.]+}",
            "/{p1:[^\\.]+}/{p2:[^\\.]+}/{p3:[^\\.]+}/{p4:[^\\.]+}/{path:[^\\.]+}",
        }
    )
    public String forward() {
        return "forward:/";
    }
}

